section.codeblock:
{
  "version": 1,
  "hooks": {
    "beforeSubmitPrompt": [
      { "command": "python3 scripts/record_prompt.py", "timeout": 5 }
    ],
    "preToolUse": [
      { "command": "python3 scripts/record_tool.py", "timeout": 5 }
    ],
    "postToolUse": [
      { "command": "python3 scripts/record_tool.py", "timeout": 5 }
    ],
    "agentFinish": [
      { "command": "python3 scripts/record_stop.py", "timeout": 5 }
    ],
    "sessionStart": [
      { "command": "python3 scripts/record_session.py", "timeout": 5 }
    ],
    "sessionEnd": [
      { "command": "python3 scripts/record_session.py", "timeout": 5 }
    ]
  }
}
